'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const n = input[0];
const heights = input.slice(1, n + 1);
const order = Array.from({ length: n }, (_, i) => i);
order.sort((a, b) => heights[b] - heights[a]);

const parent = new Int32Array(n);
const size = new Int32Array(n);
const active = new Uint8Array(n);

for (let i = 0; i < n; i++) parent[i] = i;

function find(x) {
  while (parent[x] !== x) {
    parent[x] = parent[parent[x]];
    x = parent[x];
  }
  return x;
}

function unite(a, b) {
  let ra = find(a);
  let rb = find(b);
  if (ra === rb) return false;

  if (size[ra] < size[rb]) [ra, rb] = [rb, ra];
  parent[rb] = ra;
  size[ra] += size[rb];
  return true;
}

let components = 0;
let maxComponents = 0;

for (let start = 0; start < n;) {
  let end = start + 1;
  while (end < n && heights[order[end]] === heights[order[start]]) end++;

  for (let i = start; i < end; i++) {
    const x = order[i];
    active[x] = 1;
    size[x] = 1;
    components++;
  }

  for (let i = start; i < end; i++) {
    const x = order[i];
    if (x > 0 && active[x - 1] && unite(x, x - 1)) components--;
    if (x + 1 < n && active[x + 1] && unite(x, x + 1)) components--;
  }

  maxComponents = Math.max(maxComponents, components);
  start = end;
}

console.log(maxComponents + 1);
